      solution: `<p> (a, c)<br/> •Spin locks involve busy waiting, so the CPU cycles are consumed while the process waits.<br/> Option (a) is correct.<br/> •A waiting process cannot continue executing other instructions; it is blocked until the mutex is<br/> released. Option (b) is incorrect.<br/> •Priority inversion can occur if a high-priority process spins while waiting for a low-priority<br/> process holding the lock. Option (c) is correct.<br/> •Acquiring the same mutex twice by the same process causes deadlock, unless the mutex is<br/>explicitly recursive. Option (d) is incorrect. </p>`
