      solution: `<p> (c)<br/> In the given grammar, there is no FIRST/FIRST conflict, hence it is LL(1). Now for a LL(1) grammar,<br/> if FIRST(u) ∩FIRST(v) is non-empty, there is more than one entry in the corresponding cell of the<br/> parsing table.<br/> Hence this contradicts the fact that it is a LL(1) grammar.<br/>Both (a) and (b) are true. </p>`
