      solution: `<p> (a)<br/> •In demand paging, pages are brought into main memory only when they are required by a<br/> process. This reduces the initial loading time of programs and saves memory space.<br/> Hence, the statement about programmer instruction is false, as the OS handles it automatically.<br/> So, <em>S</em> <sub>1</sub> is correct.<br/> •Dynamic linking allows multiple processes to share the same copy of library routines in<br/> memory. It avoids duplication and improves overall memory utilization efficiency. So, <em>S</em> <sub>2</sub> is correct.<br/> •Pages shared between processes can be swapped out if none of them are using those pages.<br/> When needed again, they are simply brought back into memory by the OS.<br/> Thus, the statement claiming they can never be swapped out is false. So, <em>S</em> <sub>3</sub> is incorrect. </p>`
